#pragma once

#include <cstddef>

// HDR-safe model adapter. This is not native HDR neural rendering: the model
// only sees a bounded [0,1] proxy. Highlights above 1 are reconstructed by
// residual, not generated by the network.
//
//   P = clamp_finite_01(X)
//   N = model(P)
//   Y = X + detail * (C(N) - P)
//
// C(N) is the existing Color control (chroma mix toward neural luma).
// Alpha never enters the RGB residual; output alpha is copied from X.
// detail=0 copies X exactly, including non-finite values and negatives.
// Output is not globally clamped.

void PrepareModelRgba32f(const float* src, float* proxy, size_t pixels);
void ReconstructRgba32f(const float* original, const float* proxy, const float* neural,
                        float* output, size_t pixels, float detail, float color);
